on conflict (name) do update set base_url=excluded.base_url, source_url=excluded.source_url, data_owner=excluded.data_owner, rights_decision=excluded.rights_decision, rights_reason=excluded.rights_reason, connector=excluded.connector;
insert into source_rights (source_id, approval_version, allowed_purposes, can_fetch, can_store_raw, can_publish_summary, can_make_derivatives, can_export, can_resell, attribution, retention_days, notes, approved_at, review_due_at)
select id, coalesce((select max(approval_version) from source_rights r where r.source_id = s.id), 0) + 1, '{directory,matching,verification}', true, false, true, true, false, false, data_owner, 400, rights_reason, now(), now() + interval '180 days'
from sources s where rights_decision = 'approved' and connector = 'civicplus_bids' and current_rights_id is null;
update sources s set current_rights_id = (select id from source_rights r where r.source_id = s.id order by approval_version desc limit 1)
where rights_decision = 'approved' and connector = 'civicplus_bids' and current_rights_id is null;
